## ✅ Код: `LihachTraffic.cs`

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using GTA;
using GTA.Math;
using GTA.Native;

public class LihachTraffic : Script
{
    private readonly Random _rnd = new Random();
    private DateTime _lastSpawn = DateTime.MinValue;
    private const int SpawnIntervalMs = 5000; // каждые 5 сек
    private readonly List<Vehicle> _spawnedVehicles = new List<Vehicle>();

    public LihachTraffic()
    {
        Tick += OnTick;
        Interval = 1000; // каждый фрейм — проверка для очистки
    }

    private void OnTick(object sender, EventArgs e)
    {
        var now = DateTime.Now;

        // Очистка старых машин
        _spawnedVehicles.RemoveAll(v =>
        {
            if (!v.Exists() || v.Position.DistanceTo(Game.Player.Character.Position) > 300f || (now - v.Metadata.Get<DateTime>("spawnTime")).TotalSeconds > 90)
            {
                v.Delete();
                return true;
            }
            return false;
        });

        // Генерация новых лихачей
        if ((now - _lastSpawn).TotalMilliseconds >= SpawnIntervalMs)
        {
            SpawnLihachGroup();
            _lastSpawn = now;
        }
    }

    private void SpawnLihachGroup()
    {
        var playerPos = Game.Player.Character.Position;
        var spawnPos = playerPos + World.GetNextPositionOnStreet(playerPos + new Vector3(_rnd.Next(-50, 50), _rnd.Next(-50, 50), 0));

        var r = _rnd.NextDouble();
        List<string> models = new List<string>();

        // Распределение
        if (r < 0.60) // 60% — мотоциклы
        {
            models = new List<string> { "AKUMA", "NEMESIS", "VADER", "PCJ", "BF400", "SANCHEZ2" };
            SpawnVehicles(models, spawnPos, isAggressive: true, riders: 1);
        }
        else if (r < 0.70) // +10% — авто
        {
            models = new List<string> { "BANSHEE2", "COQUETTE3", "FUTO", "COMET5", "NEON" };
            SpawnVehicles(models, spawnPos, isAggressive: true, riders: 1);
        }
        else if (r < 0.73) // +3% — грузовики
        {
            models = new List<string> { "PHANTOM2", "DUMP", "RIPLEY", "DUNE4" };
            SpawnVehicles(models, spawnPos, isAggressive: true, riders: 1);
        }
        else // 27% — одиночки-лихачи (спецтипы)
        {
            // 10% — байкер в коже
            if (_rnd.NextDouble() < 0.37) { SpawnBiker(spawnPos); }
            // 7% — гонщик-одиночка
            else if (_rnd.NextDouble() < 0.26) { SpawnRacer(spawnPos); }
            // 5% — ренегат-полицейский
            else if (_rnd.NextDouble() < 0.19) { SpawnRenegadeCop(spawnPos); }
            // 5% — безумец
            else { SpawnMadman(spawnPos); }
        }
    }

    private void SpawnVehicles(List<string> models, Vector3 pos, bool isAggressive = false, int count = 1)
    {
        for (int i = 0; i < count; i++)
        {
            var model = new Model(models[_rnd.Next(models.Count)]);
            model.Request(1000);
            if (!model.IsLoaded) continue;

            var veh = World.CreateVehicle(model, pos + new Vector3(0, i * 4f, 0));
            if (!veh) continue;

            SetupVehicle(veh, isAggressive);
            _spawnedVehicles.Add(veh);
            veh.Metadata.Set("spawnTime", DateTime.Now);
            model.MarkAsNoLongerNeeded();
        }
    }

    private void SetupVehicle(Vehicle veh, bool aggressive)
    {
        veh.EngineRunning = true;
        veh.Speed = aggressive ? _rnd.Next(30, 50) : _rnd.Next(10, 25); // км/ч → GTA units

        // Ускорение ИИ
        Function.Call(Hash.SET_VEHICLE_ENGINE_POWER_MULTIPLIER, veh, 1.4f);
        Function.Call(Hash.SET_VEHICLE_ENGINE_TORQUE_MULTIPLIER, veh, 1.3f);
        Function.Call(Hash.SET_DRIVER_AGGRESSIVENESS, veh.Driver, aggressive ? 1.0f : 0.5f);
        Function.Call(Hash.SET_DRIVER_RACING_MODIFIER, veh.Driver, aggressive ? 1.0f : 0.2f);

        // Отключаем торможение для "стада"
        if (aggressive)
            Function.Call(Hash.SET_VEHICLE_DOES_PROVIDE_COVER, veh, false);

        // Цвета — яркие/чёрные/красные (лихач-стиль)
        veh.CustomPrimaryColor = _rnd.NextDouble() > 0.5
            ? Color.Red
            : (_rnd.NextDouble() > 0.5 ? Color.Black : Color.Yellow);
    }

    private void SpawnBiker(Vector3 pos)
    {
        var veh = World.CreateVehicle("AKUMA", pos);
        var ped = veh.CreateRandomPedAsDriver();
        ped.SetComponentVariation(11, 1, 0, 2); // кожаная куртка
        ped.RemoveHelmet(true);
        ped.Weapons.Give(GTA.Native.WeaponHash.Knife, 1, true, true);
        SetupVehicle(veh, true);
        _spawnedVehicles.Add(veh);
        veh.Metadata.Set("spawnTime", DateTime.Now);
    }

    private void SpawnRacer(Vector3 pos)
    {
        var veh = World.CreateVehicle("COMET6", pos);
        veh.Mods.InstallModKit();
        veh.Mods.SetMod(VehicleModType.Livery, 3); // гоночный стиль
        veh.PrimaryColor = VehicleColor.Chrome;
        var ped = veh.CreateRandomPedAsDriver();
        ped.SetComponentVariation(11, 15, 0, 2); // гоночный комбинезон
        SetupVehicle(veh, true);
        _spawnedVehicles.Add(veh);
        veh.Metadata.Set("spawnTime", DateTime.Now);
    }

    private void SpawnRenegadeCop(Vector3 pos)
    {
        var veh = World.CreateVehicle("RIOT2", pos);
        veh.IsSirenActive = false;
        veh.IsSirenSilent = true;
        veh.Livery = 0;
        veh.CustomPrimaryColor = Color.DimGray;
        var ped = veh.CreateRandomPedAsDriver();
        ped.SetComponentVariation(11, 6, 13, 2); // полицейская форма, но без шеврона
        SetupVehicle(veh, true);
        _spawnedVehicles.Add(veh);
        veh.Metadata.Set("spawnTime", DateTime.Now);
    }

    private void SpawnMadman(Vector3 pos)
    {
        string[] madModels = { "TRICYCLE", "SANCHEZ", "BF400", "DUNE3" };
        var model = madModels[_rnd.Next(madModels.Length)];
        var veh = World.CreateVehicle(model, pos);
        veh.Mods.InstallModKit();
        veh.Mods.SetMod(VehicleModType.Livery, _rnd.Next(0, 10));
        veh.DirtLevel = 10f;
        var ped = veh.CreateRandomPedAsDriver();
        ped.SetComponentVariation(2, 1, 0, 2); // безумные очки
        SetupVehicle(veh, true);
        _spawnedVehicles.Add(veh);
        veh.Metadata.Set("spawnTime", DateTime.Now);
    }
}
```

